<?php

namespace mutation\translate\models;

use craft\db\ActiveRecord;
use yii\db\ActiveQuery;

/**
 * This is the model class for table "source_message".
 *
 * @property int $id
 * @property string $category
 * @property string $message
 * @property-read string $messageHash Generated by the database
 *
 * @property Message[] $messages
 */
class SourceMessage extends ActiveRecord
{
    public static function tableName()
    {
        return '{{%source_message}}';
    }

    /**
     * Returns the hash used to look up a message (case and accent sensitive) by its exact value.
     *
     * It must match the `messageHash` column, which is generated by the database with `MD5(message)`.
     */
    public static function hash(string $message): string
    {
        return md5($message);
    }

    /**
     * @inheritdoc
     */
    public function rules()
    {
        return [
            [['message', 'category'], 'required'],
            ['message', 'string'],
            ['category', 'string', 'max' => 255],
        ];
    }

    /**
     * @inheritdoc
     */
    public function attributeLabels()
    {
        return [
            'id' => 'ID',
            'category' => 'category',
            'message' => 'key',
        ];
    }

    /**
     * @return ActiveQuery
     */
    public function getMessages()
    {
        return $this->hasMany(Message::class, ['id' => 'id']);
    }

    public function getTranslations()
    {
        // Not ArrayHelper::map(): with objects, recent Yii versions skip the null translations
        $translations = [];
        foreach ($this->messages as $message) {
            $translations[$message->language] = $message->translation;
        }
        return $translations;
    }

    public function getTranslation($lang)
    {
        return (isset($this->translations[$lang])) ? $this->translations[$lang] : null;
    }
}
